input.newString:
# htop dashboard on tty1 — no login required
systemd.services."getty@tty1".enable = lib.mkForce false;

systemd.services.htop-console = {
  enable = true;
  description = "htop system monitor on tty1";
  after = [ "systemd-user-sessions.service" ];
  wants = [ "systemd-user-sessions.service" ];
  serviceConfig = {
    Type = "simple";
    ExecStart = "${pkgs.htop}/bin/htop";
    Restart = "always";
    RestartSec = 10;
    TTYPath = "/dev/tty1";
    StandardInput = "tty";
    StandardOutput = "tty";
    TTYReset = true;
    TTYVHangup = true;
    Environment = "TERM=linux";
  };
  wantedBy = [ "multi-user.target" ];
};

# Laptop running as a server — keep it awake.

# htop dashboard on tty1 — auto-login duck, exec htop
services.getty.autologinUser = "duck";

# Hide boot messages behind splash
boot.consoleLogLevel = 0;

programs.bash.loginShellInit = ''
  if [ "$(tty)" = "/dev/tty1" ]; then
    exec ${pkgs.htop}/bin/htop
  fi
'';

